from s114_course_common import teach
S='near-point-p1'
teach(S,'accommodation-basics-1',[
(0,'看近時，改的是水晶體形狀','睫狀肌收縮，懸韌帶反而放鬆，別把兩者動作當同方向。',[('睫狀肌ciliary muscle','收縮時減少懸韌帶張力'),('懸韌帶zonules','原本牽住水晶體；放鬆後晶體可更凸厚'),('水晶體crystalline lens','增加收光力量，幫近物重新對焦')],'不是肌肉直接捏著水晶體；這是借彈性改形的過程。'),
(2,'能加多大力、加得準不準、換得快不快','幅度、反應、靈敏度不是同一個分數。',[('AA幅度','從最放鬆到最大可增加的D'),('反應response','實際用了多少；不足lag落後，過多lead導程'),('Facility靈敏度','在指定條件下切換焦點的能力，常記循環／分')],'反應慢不一定AA低；AA正常也可能切換困難。'),
(4,'近點與遠點，是目標位置，不是眼內焦點','先定義符號，才不會把近視負號扣錯。',[('FP遠點','調節放鬆時的共軛目標位置，遠視可在眼後為虛點'),('NPA近點','調節用到最大時眼前能清楚的最近位置'),('AA','R取近視負、遠視正時，AA＝1/NPA(m)+R')],'正視／全矯正R≈0，才可AA≈1/NPA；眼後虛遠點不是把真實物體塞到眼後。')])
teach(S,'amplitude-interpretation-1',[
(0,'Hofstetter是年齡參考，不是你已實測的能力','算式給群體預期，量測才知道此人的結果。',[('最小','15−0.25×年齡'),('平均','18.5−0.30×年齡'),('最大','25−0.40×年齡，單位都是D')],'50歲最小2.5D；不能把公式外推到高齡負值就說有負調節能力。'),
(2,'調節不足：不只問看得到，還問撐不撐得住','看近疲累不是調節不足的唯一病因證明。',[('常見症狀','持續模糊、眼痠、額頭痛、閱讀不耐久'),('檢查','遠用矯正、AA、調節反應、切換等一起評估'),('處理目的','按原因以近用正加入度分擔、或適當視覺訓練等')],'老花的水晶體老化不能用訓練保證恢復年輕的調節幅度。'),
(4,'比較兩眼前，先確認用同一種測法','一眼差很多，是重測與查原因的線索。',[('矯正與起始距離','兩眼要一致，別把度數沒矯正當AA差'),('終點','都以持續模糊，避免一眼報閃糊、一眼硬撐'),('用藥／眼部原因','抗膽鹼藥、外傷炎症或副交感問題等需考慮')],'課堂約1D差距是比較線索，不是單靠一個差值就完成診斷。')])
teach(S,'npa-methods-1',[
(0,'推近：字一直糊，才記近點','一閃模糊但能再清楚，不是本課的終點。',[('準備','戴遠用最佳矯正，單眼看清小字'),('慢慢移近','依課堂速度，問是否持續模糊'),('記距離','註明測量起點與cm，換成m才取倒數')],'推近時字看起來也變大、景深有影響，所以測得AA不一定等於純水晶體能力。'),
(2,'拉遠：從已模糊的位置，退到重新清楚','移動方向和終點都與推近相反。',[('起點','視標太近、已模糊'),('動作','慢慢往外移'),('終點','第一次重新看清並維持的距離')],'推近和拉遠有方法差；若課堂取平均要註明，不能把不同方法當完全可互換。'),
(4,'負鏡片法：目標不動，讓鏡片增加需求','算新增負鏡，不是把原近視處方也算成調節。',[('40cm需求','本來就需要2.50D'),('再加−2D','新需求增加2D，AA近似2.5+2＝4.5D'),('更近目標','先以1/d重算距離需求，不能固定都加2.5')],'每次增加−0.25D，依課堂間隔找持續模糊；特殊題要求的縮小補償另依題意，不一律扣0.5。')])
teach(S,'npc-1',[
(0,'對焦和對準：看糊，與看成兩個不同','NPA問水晶體對焦；NPC問兩眼集合維持單視。',[('Version共同運動','兩眼同向，如一起向右看'),('Vergence異向運動','兩眼相反轉，會聚向內、開散向外'),('NPC','near point of convergence，集合近點，用cm記')],'它不是用1/距離直接算調節幅度的那個近點。'),
(2,'先移近到分開，再移遠到合一','break與recovery是一進一退的兩個位置。',[('Break破裂','第一次複視，或觀察到一眼偏開'),('Recovery恢復','移遠後再次單視'),('5/8cm','5cm破裂，8cm恢復；通常恢復點較遠')],'若一眼抑制，可能沒報複視，仍需觀察眼位與使用的視標。'),
(4,'字卡帶來調節幫忙，筆燈的條件不同','不同視標可給線索，但差很多不等於單項確診CI。',[('調節性字卡','細節引出調節，可能帶動集合'),('筆燈／紅鏡','條件不同，可能較易發現分開'),('CI集合不足','要結合近遠眼位、融像聚散與症狀等')],'記視標、距離基準、break/recovery與重複次數，才能可靠比較。')])
